#!/bin/bash
# Detect A->B->A blob reversion patterns on first-parent main since 2026-05-27.
# Output: per-path collapsed blob sequences (oldest->newest) where a blob value reappears.
set -euo pipefail
cd /Users/luke/Projects/personal/my-pi

revs=$(git rev-list --first-parent --since=2026-05-27 origin/main | tail -r)  # oldest -> newest

: > /tmp/cf-audit/tree-dump.txt
i=0
for rev in $revs; do
  i=$((i+1))
  git ls-tree -r --format="$i $rev %(objectname) %(path)" "$rev" -- extensions packages scripts src .github >> /tmp/cf-audit/tree-dump.txt
done
echo "revs: $i, lines: $(wc -l < /tmp/cf-audit/tree-dump.txt)"

awk '
{
  idx=$1; rev=$2; blob=$3; $1=""; $2=""; $3=""; sub(/^   /,""); path=$0;
  if (path ~ /node_modules\//) next;
  key=path;
  if (last[key] != blob) {
    seq[key] = seq[key] " " blob "@" idx;
    last[key] = blob;
    count[key]++;
  }
}
END {
  for (k in seq) {
    if (count[k] < 3) continue;  # need at least A B A
    n = split(seq[k], parts, " ");
    delete seen;
    flagged = 0;
    for (i = 1; i <= n; i++) {
      split(parts[i], pb, "@");
      b = pb[1];
      if (b in seen) { flagged = 1; break; }
      seen[b] = 1;
    }
    if (flagged) print "REVERTED:", k, "::", seq[k];
  }
}' /tmp/cf-audit/tree-dump.txt > /tmp/cf-audit/reverted-files.txt
wc -l /tmp/cf-audit/reverted-files.txt

